const lv_image_dsc_t weather_icon_exceptional = {
    .header = {
        .magic = LV_IMAGE_HEADER_MAGIC,
        .cf = LV_COLOR_FORMAT_L8,
        .flags = 0,
        .w = 40,
        .h = 40,
        .stride = 40,
        .reserved_2 = 0,
    },
    .data_size = 1600,
    .data = weather_icon_exceptional_map,
    .reserved = NULL,
    .reserved_2 = NULL,
};

const lv_image_dsc_t *weather_icon_for_condition(const char *condition, bool night) {
    if (condition == NULL || condition[0] == '\0') {
        return &weather_icon_cloudy;
    }
    if (strcmp(condition, "sunny") == 0) {
        return &weather_icon_sunny;
    }
    if (strcmp(condition, "clear-night") == 0) {
        return &weather_icon_clear_night;
    }
    if (strcmp(condition, "partlycloudy") == 0) {
        return night ? &weather_icon_partlycloudy_night : &weather_icon_partlycloudy;
    }
    if (strcmp(condition, "cloudy") == 0) {
        return &weather_icon_cloudy;
    }
    if (strcmp(condition, "fog") == 0) {
        return &weather_icon_fog;
    }
    if (strcmp(condition, "hail") == 0) {
        return &weather_icon_hail;
    }
    if (strcmp(condition, "lightning") == 0) {
        return &weather_icon_lightning;
    }
    if (strcmp(condition, "lightning-rainy") == 0) {
        return &weather_icon_lightning_rainy;
    }
    if (strcmp(condition, "pouring") == 0) {
        return &weather_icon_pouring;
    }
    if (strcmp(condition, "rainy") == 0) {
        return &weather_icon_rainy;
    }
    if (strcmp(condition, "snowy") == 0) {
        return &weather_icon_snowy;
    }
    if (strcmp(condition, "snowy-rainy") == 0) {
        return &weather_icon_snowy_rainy;
    }
    if (strcmp(condition, "windy") == 0) {
        return &weather_icon_windy;
    }
    if (strcmp(condition, "windy-variant") == 0) {
        return &weather_icon_windy_variant;
    }
    if (strcmp(condition, "exceptional") == 0) {
        return &weather_icon_exceptional;
    }
    return &weather_icon_cloudy;
}
